38	bool NgramsTokenizer::nextInStringLike(const char * data, size_t length, size_t & pos, String & token) const
39	{
40	    token.clear();
41	
42	    size_t code_points = 0;
43	    bool escaped = false;
44	    for (size_t i = pos; i < length;)
45	    {
46	        if (escaped && (data[i] == '%' || data[i] == '_' || data[i] == '\\'))
47	        {
48	            token += data[i];
49	            ++code_points;
50	            escaped = false;
51	            ++i;
52	        }
53	        else if (!escaped && (data[i] == '%' || data[i] == '_'))
54	        {
55	            /// This token is too small, go to the next.
56	            token.clear();
57	            code_points = 0;
58	            escaped = false;
59	            ++i;
60	            pos = i;
61	        }
62	        else if (!escaped && data[i] == '\\')
63	        {
64	            escaped = true;
65	            ++i;
66	        }
67	        else
68	        {
69	            const size_t sz = UTF8::seqLength(static_cast<UInt8>(data[i]));
70	            /// The sequence length is determined by the first character, but we should always check it does not go beyond the buffer length.
71	            for (size_t j = 0; j < sz && i + j < length; ++j)
72	                token += data[i + j];
73	            i += sz;
74	            ++code_points;
75	            escaped = false;
76	        }
77	
78	        if (code_points == n)
79	        {
80	            pos += UTF8::seqLength(static_cast<UInt8>(data[pos]));
81	            return true;
82	        }
83	    }
84	
85	    return false;
86	}
