98	bool SplitByNonAlphaTokenizer::nextInString(const char * data, size_t length, size_t & __restrict pos, size_t & __restrict token_start, size_t & __restrict token_length) const
99	{
100	    token_start = pos;
101	    token_length = 0;
102	
103	    while (pos < length)
104	    {
105	        if (isASCII(data[pos]) && !isAlphaNumericASCII(data[pos]))
106	        {
107	            /// Finish current token if any
108	            if (token_length > 0)
109	                return true;
110	            token_start = ++pos;
111	        }
112	        else
113	        {
114	            /// Note that UTF-8 sequence is completely consisted of non-ASCII bytes.
115	            ++pos;
116	            ++token_length;
117	        }
118	    }
119	
120	    return token_length > 0;
121	}
122	
123	bool SplitByNonAlphaTokenizer::nextInStringLike(const char * data, size_t length, size_t & pos, String & token) const
124	{
125	    token.clear();
126	    bool bad_token = false; // % or _ before token
127	    bool escaped = false;
128	    while (pos < length)
129	    {
130	        if (!escaped && (data[pos] == '%' || data[pos] == '_'))
131	        {
132	            /// Unescaped wildcard: invalidates current token
133	            token.clear();
134	            bad_token = true;
135	            ++pos;
136	        }
137	        else if (!escaped && data[pos] == '\\')
138	        {
139	            escaped = true;
140	            ++pos;
141	        }
142	        else if (isASCII(data[pos]) && !isAlphaNumericASCII(data[pos]))
143	        {
144	            /// Non-alphanumeric ASCII is a separator (including escaped \_ and \%)
145	            if (!bad_token && !token.empty())
146	            {
147	                ++pos; /// consume separator before returning
148	                return true;
149	            }
150	
151	            token.clear();
152	            bad_token = false;
153	            escaped = false;
154	            ++pos;
155	        }
156	        else
157	        {
158	            const size_t sz = UTF8::seqLength(static_cast<UInt8>(data[pos]));
159	            /// The sequence length is determined by the first character, but we should always check it does not go beyond the buffer length.
160	            for (size_t j = 0; j < sz && pos < length; ++j)
161	            {
162	                token += data[pos];
163	                ++pos;
164	            }
165	            escaped = false;
166	        }
167	    }
168	
169	    return !bad_token && !token.empty();
170	}
