175	/// Shared implementation of `substringToBloomFilter` for word-boundary tokenizers
176	/// (`SplitByNonAlphaTokenizer`, `AsciiCJKTokenizer`).
177	///
178	/// In order to avoid filter updates with incomplete tokens, the first token is
179	/// ignored unless the substring is a prefix, and the last token is ignored unless
180	/// the substring is a suffix.
181	/// Ex: If we want to match row "Service is not ready", and substring is "Serv"
182	/// or "eady", we don't want to add either of these substrings as tokens since
183	/// they will not match any of the real tokens. However if our token string is
184	/// "Service " or " not ", we want to add these full tokens to our bloom filter.
185	template <typename Tokenizer>
186	void wordBoundarySubstringToBloomFilter(
187	    const Tokenizer & tokenizer, const char * data, size_t length, BloomFilter & bloom_filter, bool is_prefix, bool is_suffix)
188	{
189	    size_t cur = 0;
190	    size_t token_start = 0;
191	    size_t token_len = 0;
192	
193	    while (cur < length && tokenizer.nextInString(data, length, cur, token_start, token_len))
194	        if ((token_start > 0 || is_prefix) && (token_start + token_len < length || is_suffix))
195	            bloom_filter.add(data + token_start, token_len);
196	}
197	
198	/// Shared implementation of `substringToTokens` for word-boundary tokenizers.
199	/// Same boundary-filtering logic as `wordBoundarySubstringToBloomFilter`.
200	template <typename Tokenizer>
201	void wordBoundarySubstringToTokens(
202	    const Tokenizer & tokenizer, const char * data, size_t length, std::vector<String> & tokens, bool is_prefix, bool is_suffix)
203	{
204	    size_t cur = 0;
205	    size_t token_start = 0;
206	    size_t token_len = 0;
